ExecutorService pool = Executors.newFixedThreadPool(2);
for (int i = 1; i <= 3; i++) {
    pool.execute(new UploadResult("UploadResult:" + i));
}
pool.shutdown();
while (!pool.isTerminated()) { }
System.out.println("Finished all threads");

public class UploadResult implements Callable<Boolean> {
    @Override
    public Boolean call() throws Exception {
        // Simulate upload logic
        try {
            Thread.sleep(2000);
            return Boolean.TRUE; // Successful upload
        } catch (Exception e) {
            return Boolean.FALSE; // Failed upload
        }
    }
}

ExecutorService exService = Executors.newSingleThreadExecutor();
Future<Boolean> future = exService.submit(new UploadResult());
try {
    System.out.println("Upload completed: " + future.get()); // Get the result
} catch (InterruptedException | ExecutionException e) {
    System.out.println(e.getMessage());
}
exService.shutdown();

ReentrantLock lock = new ReentrantLock(true); // Fair lock
lock.lock();
// Critical section code
lock.unlock();

class UploadResultWithLock implements Runnable {
    private ReentrantLock lock;
    private int resultCount = 0;

    public UploadResultWithLock(ReentrantLock lock) {
        this.lock = lock;
    }

    @Override
    public void run() {
        try {
            lock.lock();
            // Simulate uploading result
            Thread.sleep(2000);
            resultCount++; // Increment count safely
        } catch (InterruptedException e) {
            System.out.println(e.getMessage());
        } finally {
            lock.unlock();
        }
    }
}

public static void main(String[] args) {
    ExecutorService exServicePool = Executors.newFixedThreadPool(2);  // 2 threads
    ReentrantLock lock = new ReentrantLock();  // Create lock
    UploadResultWithLock uploadRunnable = new UploadResultWithLock(lock);

    for (int i = 0; i < 3; i++) {
        exServicePool.execute(uploadRunnable);  // Submit 3 tasks
    }

    exServicePool.shutdown();
    while (!exServicePool.isTerminated()) { }  // Wait until all threads are finished
    System.out.println("Finished all threads");
}

